  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Connection is dead; log if needed but don't mask the original error
    }
    throw err;
  } finally {
    client.release();
  }
}
