const db = require("../db");

const router = express.Router();
const idempotencyStore = new Map();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header required" });
  }

  const storeKey = `${req.user.accountId}:${idempotencyKey}`;
  if (idempotencyStore.has(storeKey)) {
    const cached = idempotencyStore.get(storeKey);
    return res.status(201).json(cached);
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );
  idempotencyStore.set(storeKey, row);
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(403).end();
  res.json(row);
});

module.exports = router;

turns.text:
If a connection drops mid-write, the behavior depends on when it fails:

**Before the query executes** (after BEGIN, before line 17): The query throws a connection error. The catch block tries `ROLLBACK` on a dead connection, which also throws. That error propagates to the caller; the transaction is abandoned and eventually rolled back by the server.

**During or after the query** (before COMMIT reaches the server): The query might have partially executed before the drop. The `COMMIT` fails with a connection error. The catch block attempts `ROLLBACK` on a dead connection, which fails again. The error propagates to the caller; the transaction is left open on the server until it times out.

**Core issue**: The ROLLBACK in the catch block assumes the connection is alive. If it's dead, the ROLLBACK itself throws, masking the original error and leaving transactions open. The caller sees an error but doesn't know if the write succeeded, partially succeeded, or never started.

Better approach is to suppress the ROLLBACK error and always release the connection:

```javascript
async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // ROLLBACK failed; connection is likely dead. Ignore and let release() handle cleanup.
    }
    throw err;
  } finally {
    client.release();
  }
}
```

This ensures the connection always gets released and the original error reaches the caller.

db.js.text:
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.PGHOST,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

// Callers check out a client and are responsible for releasing it.
async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}

module.exports = { pool, withClient };

