const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get('Idempotency-Key');

  if (idempotencyKey) {
    const cached = await db.query(
      "SELECT response_body FROM idempotency_keys WHERE account_id = $1 AND key = $2",
      [req.user.accountId, idempotencyKey]
    );
    if (cached.length) {
      return res.status(201).json(JSON.parse(cached[0].response_body));
