    logResponse(res.statusCode);
    return originalJson.call(this, data);
  };

  res.end = function(...args) {
    if (!res.statusCode) return originalEnd.apply(this, args);
    logResponse(res.statusCode);
    return originalEnd.apply(this, args);
  };

  next();
});

