const express = require("express");
const db = require("../db");

const router = express.Router();
const idempotencyCache = new Map();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers["idempotency-key"];
  if (idempotencyKey) {
    const cacheKey = `${req.user.accountId}:${idempotencyKey}`;
    const cached = idempotencyCache.get(cacheKey);
    if (cached) return res.status(201).json(cached);
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  if (idempotencyKey) {
    const cacheKey = `${req.user.accountId}:${idempotencyKey}`;
    idempotencyCache.set(cacheKey, row);
  }

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

turns.text:
If the connection drops during write(), the request crashes. Here's the sequence:

1. `pool.connect()` gets a client
2. `BEGIN` starts a transaction
3. The UPDATE/INSERT query runs, then the connection drops
4. The query throws an error (connection lost)
5. The catch block tries `client.query("ROLLBACK")`, but the connection is already dead, so that also fails
6. That ROLLBACK error replaces the original and gets thrown up
7. The route handler crashes with an unhandled exception
8. No HTTP response is sent
9. On the server side, PostgreSQL rolls back the transaction after detecting the dropped connection

The issue: if the connection drops *during* COMMIT (after the query succeeds), the database might apply the write before the connection closes, but ROLLBACK still tries to run and fails. The result is unpredictable—the write may or may not persist depending on timing.

The fix would be to handle connection errors more gracefully in the catch block:

```javascript
catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      // Connection already dead, that's fine
    }
    throw err;
  }
```

This way a connection error doesn't mask the original query error, and the route handler can catch and respond appropriately.

